// PayPal's own Server SDK (@paypal/paypal-server-sdk 2.5.0, generated by APIMatic), used for the
// reporting calls: balances and Transaction Search. Set up the way the APIMatic Context Plugin for
// PayPal's TypeScript guides say (docs/architecture.md, Phase 10), each choice checked against the
// SDK's source:
// - one SDK client per PayPalClient, built once and reused (it caches its OAuth token);
// - an explicit timeout per attempt, because the SDK's default of 0 means no timeout at all;
// - retries on GET only, with a wait budget, because the SDK's defaults retry nothing; by status
//   only, not on "timeouts" (see retryOnTimeout below);
// - a token provider that never rejects: a rejected token fetch would stay cached as the client's
//   token and fail every later call until the process restarts;
// - our rate limiter on every attempt, token requests included, through a request interceptor.
// The hand-written client (client.ts) still moves the money: Payouts are not in this SDK.
import { ApiError, ArgumentsValidationError, Client, ClientCredentialsAuthManager, Environment, ResponseValidationError } from "@paypal/paypal-server-sdk";
import type { ApiResponse, OAuthToken } from "@paypal/paypal-server-sdk";
import { pino } from "pino";
import type { PayPalClientOptions } from "./client.ts";
import { issueOf, PayPalApiError, PayPalNetworkError } from "./errors.ts";

/** The only PayPal host this SDK client talks to. */
export const SANDBOX_API = "https://api-m.sandbox.paypal.com";

/** A stand-in PayPal on this machine (the e2e run's fake), reached by rewriting the sandbox URL. */
const LOCAL_STAND_IN = /^http:\/\/(127\.0\.0\.1|localhost)(:\d{1,5})?$/;

type Factory = ReturnType<Client["getRequestBuilderFactory"]>;
type Interceptor = Parameters<ReturnType<Factory>["intercept"]>[0];

const log = pino({ name: "paypal-sdk" });

/** Where requests go: null for the sandbox itself, or a local stand-in's origin. Anything else is refused. */
export function standInFor(baseUrl: string): string | null {
  const b = baseUrl.replace(/\/+$/, "");
  if (b === SANDBOX_API) return null;
  if (LOCAL_STAND_IN.test(b)) return b;
  throw new Error(`the PayPal SDK client only talks to the sandbox (${SANDBOX_API}) or a local stand-in, not ${b}`);
}

export class PayPalSdk {
  readonly client: Client;
  /** The last token fetch that failed, reported with the call that needed it. */
  private tokenFailure: unknown;
  private readonly logger: PayPalClientOptions["logger"];

  constructor(o: PayPalClientOptions) {
    const standIn = standInFor(o.baseUrl);
    this.logger = o.logger;
    const attempts = o.maxAttempts ?? 4;
    const client = new Client({
      environment: Environment.Sandbox,
      timeout: o.timeoutMs ?? 15_000,
      clientCredentialsAuthCredentials: {
        oAuthClientId: o.clientId,
        oAuthClientSecret: o.clientSecret,
        // Refresh five minutes early, like the hand-written client.
        oAuthClockSkew: 300,
        oAuthTokenProvider: async (last, manager) => {
          try {
            const token = await manager.fetchToken();
            this.tokenFailure = undefined;
            return token;
          } catch (err) {
            this.tokenFailure = err;
            // Expired, so the next call fetches again instead of re-throwing this failure forever.
            return { accessToken: last?.accessToken ?? "", tokenType: last?.tokenType ?? "Bearer", expiry: 0n } satisfies OAuthToken;
          }
        },
      },
      httpClientOptions: {
        retryConfig: {
          maxNumberOfRetries: attempts - 1,
          retryInterval: 0.5,
          backoffFactor: 2,
          maximumRetryWaitTime: 20,
          // Off on purpose. The runtime (@apimatic/core 0.10.30, retry interceptor) counts every error
          // thrown inside its retry step as a timeout, and an answer the operation maps to a typed
          // error (balances: 400, 403, 500) is thrown there. With this on, PayPal's definite "no"
          // was sent again three times. So a network failure isn't retried here: the money page
          // refuses and can be asked again, and the worker tries again on its next run.
          retryOnTimeout: false,
          httpStatusCodesToRetry: [408, 429, 500, 502, 503, 504],
          // GET only: these calls read; the SDK's default would also retry PUT.
          httpMethodsToRetry: ["GET"],
        },
      },
      // Unit tests hand in a fake fetch; the SDK's transport seam is an axios adapter.
      ...(o.fetch ? { unstable_httpClientOptions: { adapter: fetchAdapter(o.fetch) } } : {}),
    });

    const base = client.getRequestBuilderFactory();
    const perAttempt: Interceptor = async (req, opt, next) => {
      await o.limiter.take();
      return next(standIn && req.url.startsWith(SANDBOX_API) ? { ...req, url: standIn + req.url.slice(SANDBOX_API.length) } : req, opt);
    };
    const factory: Factory = (...args) => {
      const rb = base(...args);
      rb.intercept(perAttempt);
      return rb;
    };
    client.getRequestBuilderFactory = () => factory;
    // The token manager built its OAuth controller from the factory before we wrapped it; rebuild it
    // over the wrapped one, or token requests would skip the limiter and the stand-in.
    client.clientCredentialsAuthManager = new ClientCredentialsAuthManager({ oAuthClientId: o.clientId, oAuthClientSecret: o.clientSecret, oAuthClockSkew: 300 }, client);
    this.client = client;
  }

  /** Runs one SDK call and returns its result, with errors in this package's own types. */
  async call<T>(path: string, run: (client: Client) => Promise<ApiResponse<T>>): Promise<T> {
    try {
      return (await run(this.client)).result;
    } catch (err) {
      throw this.translate(path, err);
    }
  }

  private translate(path: string, err: unknown): unknown {
    if (err instanceof ApiError) {
      const body = err.result ?? parseBody(err.body);
      const debugId = err.headers?.["paypal-debug-id"];
      (this.logger ?? log).warn({ method: "GET", path, status: err.statusCode, debugId, issue: issueOf(body) }, "paypal error");
      return new PayPalApiError(err.statusCode, body, path, debugId);
    }
    // Our own arguments, or PayPal's answer not matching the SDK's schema: not a network problem.
    if (err instanceof ResponseValidationError || err instanceof ArgumentsValidationError) return err;
    if (this.tokenFailure !== undefined) {
      const failure = this.tokenFailure;
      this.tokenFailure = undefined;
      return this.translate("/v1/oauth2/token", failure);
    }
    return new PayPalNetworkError(path, err);
  }
}

function parseBody(body: unknown): unknown {
  if (typeof body !== "string" || body === "") return body;
  try {
    return JSON.parse(body);
  } catch {
    return { raw: body.slice(0, 2000) };
  }
}

interface AxiosLikeConfig {
  url?: string;
  method?: string;
  headers?: unknown;
  data?: unknown;
  timeout?: number;
}

/** An axios adapter over a fetch function: the SDK's documented test seam, used only when a fetch is injected. */
function fetchAdapter(f: typeof fetch) {
  return async (config: AxiosLikeConfig) => {
    const h = config.headers as { toJSON?: () => Record<string, unknown> } | Record<string, unknown> | undefined;
    const raw = (h && typeof h.toJSON === "function" ? h.toJSON() : (h ?? {})) as Record<string, unknown>;
    const headers = Object.fromEntries(Object.entries(raw).filter(([, v]) => v !== undefined && v !== null).map(([k, v]) => [k, String(v)]));
    const res = await f(config.url ?? "", {
      method: (config.method ?? "get").toUpperCase(),
      headers,
      ...(config.data === undefined || config.data === null ? {} : { body: String(config.data) }),
      ...(config.timeout ? { signal: AbortSignal.timeout(config.timeout) } : {}),
    });
    return { data: await res.text(), status: res.status, statusText: res.statusText, headers: Object.fromEntries(res.headers), config, request: {} };
  };
}
